import{_ as e,o as a,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Abrir processo migrado no PJe","description":"","frontmatter":{"title":"Abrir processo migrado no PJe","id":"eproc-abrir-processo-pje","plataforma":"eproc","tribunal":"TJMG","grupo":"Migração PJe (TJMG)","plano":"free","desde":"1.15.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-abrir-processo-pje"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-abrir-processo-pje"}],["meta",{"property":"og:title","content":"Abrir processo migrado no PJe | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-abrir-processo-pje.md","filePath":"funcionalidades/eproc-abrir-processo-pje.md"}'),i={name:"funcionalidades/eproc-abrir-processo-pje.md"};function c(n,o,p,l,t,d){return a(),r("div",null,o[0]||(o[0]=[s('<h1 id="abrir-processo-migrado-no-pje" tabindex="-1">Abrir processo migrado no PJe <a class="header-anchor" href="#abrir-processo-migrado-no-pje" aria-label="Permalink to &quot;Abrir processo migrado no PJe&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Em processos migrados do PJe para o eproc, abre o mesmo processo no PJe do TJMG numa aba nova, para consultar o histórico original. O eploc faz a consulta processual pelo número e, quando ela encontra o processo, já abre os detalhes dele.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc do TJMG</strong>, página do processo, só em processos com o aviso &quot;Processo Migrado&quot; no topo: um ícone de abrir em nova aba ao lado do número do processo. O próprio aviso &quot;Processo Migrado&quot; também fica clicável e faz o mesmo.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo migrado no eproc.</li><li>Clique no ícone ao lado do número do processo (ou no aviso &quot;Processo Migrado&quot;).</li><li>Na primeira vez, o eploc abre as configurações e pede acesso ao PJe (<code>pje.tjmg.jus.br</code>). Clique em <strong>Permitir</strong>, confirme no navegador, volte ao processo e clique de novo.</li><li>O PJe abre numa aba ao lado, com o número pesquisado na consulta processual. Quando a consulta encontra exatamente esse processo, os detalhes se abrem na mesma aba.</li></ol><p>Enquanto o PJe carrega, o ícone gira. Se algo der errado (por exemplo, a sessão do PJe expirou), o ícone vira um alerta por alguns segundos; passe o mouse para ver o motivo.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>É preciso estar logado no PJe. Se a sessão tiver expirado, entre no PJe na aba que se abriu e clique de novo no atalho.</li><li>A pesquisa passa pelo reCAPTCHA do próprio PJe, como uma consulta feita à mão. Se o PJe recusar, a aba fica na consulta para você pesquisar.</li><li>O número do processo só vai ao PJe quando você clica no atalho. Veja <a href="./../privacidade">Privacidade e dados</a>.</li></ul>',12)]))}const b=e(i,[["render",c]]);export{m as __pageData,b as default};
